INSERT INTO public.inspection_base_items (item_id, section_id, section_title, parent_section_id, text, sort_order, is_active) VALUES ('17.3.5.1', '17', '17.3.5.1 "피난용 호출"이라고 명확히 표시된 ''피난호출 스위치''가 지정된 피난 층에 위치되어야 한다. 이 피난 호출스위치는 승강장문 끝부분에서 수평으로 2 m 이내에 위치되고, 바닥 위로 높이 1.4 m부터 2.0 m 이내에 위치되어야 한다.', '17.3.5', '17.3.5.1 "피난용 호출"이라고 명확히 표시된 ''피난호출 스위치''가 지정된 피난 층에 위치되어야 한다. 이 피난 호출스위치는 승강장문 끝부분에서 수평으로 2 m 이내에 위치되고, 바닥 위로 높이 1.4 m부터 2.0 m 이내에 위치되어야 한다.', 173051, 'true') ON CONFLICT (item_id) DO UPDATE SET text = EXCLUDED.text, section_title = EXCLUDED.section_title, updated_at = now();
INSERT INTO public.inspection_base_items (item_id, section_id, section_title, parent_section_id, text, sort_order, is_active) VALUES ('17.3.5.2', '17', '17.3.5.2 ''피난호출 스위치''는 전면이 보이는 재질(유리 또는 투명한 아크릴 등)로 된 박스로 보호되어야 한다.', '17.3.5', '17.3.5.2 ''피난호출 스위치''는 전면이 보이는 재질(유리 또는 투명한 아크릴 등)로 된 박스로 보호되어야 한다.
<2014년 7월 1일 이후 건축허가분부터 적용>', 173052, 'true') ON CONFLICT (item_id) DO UPDATE SET text = EXCLUDED.text, section_title = EXCLUDED.section_title, updated_at = now();
INSERT INTO public.inspection_base_items (item_id, section_id, section_title, parent_section_id, text, sort_order, is_active) VALUES ('17.3.5.3', '17', '17.3.5.3 피난용 엘리베이터가 2개의 출입구를 갖고 보호된 경우, 피난용 엘리베이터 로비는 피난 층의 로비와 같은 측면에 모두 위치되어야 하고, ''피난호출 스위치''는 방화 구획된 로비 측면에 위치되어야 한다.', '17.3.5', '17.3.5.3 피난용 엘리베이터가 2개의 출입구를 갖고 보호된 경우, 피난용 엘리베이터 로비는 피난 층의 로비와 같은 측면에 모두 위치되어야 하고, ''피난호출 스위치''는 방화 구획된 로비 측면에 위치되어야 한다.', 173053, 'true') ON CONFLICT (item_id) DO UPDATE SET text = EXCLUDED.text, section_title = EXCLUDED.section_title, updated_at = now();
INSERT INTO public.inspection_base_items (item_id, section_id, section_title, parent_section_id, text, sort_order, is_active) VALUES ('17.3.5.4', '17', '17.3.5.4 ''피난호출'' 또는 ''피난운전'' 중에 모든 엘리베이터 안전장치(전기적 및 기계적)는 모두 작동상태이어야 한다. 다만, 문닫힘안전장치는 제외한다.', '17.3.5', '17.3.5.4 ''피난호출'' 또는 ''피난운전'' 중에 모든 엘리베이터 안전장치(전기적 및 기계적)는 모두 작동상태이어야 한다. 다만, 문닫힘안전장치는 제외한다.', 173054, 'true') ON CONFLICT (item_id) DO UPDATE SET text = EXCLUDED.text, section_title = EXCLUDED.section_title, updated_at = now();
INSERT INTO public.inspection_base_items (item_id, section_id, section_title, parent_section_id, text, sort_order, is_active) VALUES ('17.3.5.5', '17', '17.3.5.5 ''피난호출 스위치''는 점검운전 제어(16.15), 정지장치(16.1.11) 또는 전기적 비상운전 제어(16.1.6)보다 우선되지 않아야 한다.', '17.3.5', '17.3.5.5 ''피난호출 스위치''는 점검운전 제어(16.15), 정지장치(16.1.11) 또는 전기적 비상운전 제어(16.1.6)보다 우선되지 않아야 한다.', 173055, 'true') ON CONFLICT (item_id) DO UPDATE SET text = EXCLUDED.text, section_title = EXCLUDED.section_title, updated_at = now();
INSERT INTO public.inspection_base_items (item_id, section_id, section_title, parent_section_id, text, sort_order, is_active) VALUES ('17.3.5.6', '17', '17.3.5.6 피난 호출 및 피난 운전 중일 때 피난용 엘리베이터의 기능은 승강장 호출 제어 또는 승강로 외부에 위치한 제어 시스템의 다른 부품의 전기적 고장에 의해 영향을 받지 않아야 한다. 피난용 엘리베이터와 같은 그룹운전에 있는 다른 엘리베이터의 전기적 고장이 피난용 엘리베이터의 운전에 영향을 주지 않아야 한다.', '17.3.5', '17.3.5.6 피난 호출 및 피난 운전 중일 때 피난용 엘리베이터의 기능은 승강장 호출 제어 또는 승강로 외부에 위치한 제어 시스템의 다른 부품의 전기적 고장에 의해 영향을 받지 않아야 한다. 피난용 엘리베이터와 같은 그룹운전에 있는 다른 엘리베이터의 전기적 고장이 피난용 엘리베이터의 운전에 영향을 주지 않아야 한다.', 173056, 'true') ON CONFLICT (item_id) DO UPDATE SET text = EXCLUDED.text, section_title = EXCLUDED.section_title, updated_at = now();
INSERT INTO public.inspection_base_items (item_id, section_id, section_title, parent_section_id, text, sort_order, is_active) VALUES ('17.3.5.7', '17', '17.3.5.7 피난용 엘리베이터에 대한 우선 호출(피난호출)', '17.3.5', '17.3.5.7 피난용 엘리베이터에 대한 우선 호출(피난호출)
피난용 엘리베이터의 호출(피난 호출)은 17.3.5.1에 따른 ''피난호출 스위치''의 조작 또는 건축물의 방재시스템에서 발동하는 화재경보신호에 의해 수동 또는 자동으로 다음 각 호와 같이 시작되어야 한다.
가) 승강로 및 기계류 공간의 조명은 17.3.5.1에 따른 ''피난호출 스위치''가 조작되면 자동으로 점등되어야 한다.
나) 모든 승강장 호출 및 카 내의 등록버튼은 작동되지 않아야 하고, 미리 등록된 호출은 취소되어야 한다.
다) 문 열림 버튼 및 비상통화(16.3) 버튼은 작동이 가능한 상태이어야 한다.
라) 그룹운전에서 피난용 엘리베이터는 다른 모든 엘리베이터와 독립적으로 기능되어야 한다.
마) 17.3.7에 따른 피난 활동 통화시스템은 작동되어야 한다.
바) 카 조작반에 있는 시각적 표시기는 작동되어야 한다. 이 시각적 표시기는 엘리베이터가 정상 작동으로 복귀될 때까지 작동상태가 유지되어야 한다.
사) ''피난호출 스위치'' 조작 시 점검운전 제어, 정지장치, 전기적 비상운전 제어 또는 기타 유지관리 통제 조건하에 있을 때 즉시 카 및 관련 기계류 공간에 경보(가청신호)가 울려야 한다. 이 경보음 크기는 55 dB에 설정하고 35 dB와 65 dB 사이에서 조정이 가능해야 한다. 경보음은 엘리베이터가 점검운전 제어, 정지장치, 전기적 비상운전 제어 또는 기타 유지관리 통제 조건이 해제될 때 멈추고, 자동으로 피난운전이 계속된다.
아) 승강장에 문을 열고 대기하고 있는 피난용 엘리베이터는 문을 닫고 피난 층까지 멈추지 않고 이동되어야 한다. 경보음은 문이 닫힐 때까지 카 내에서 울려야 한다. 승강장문이 실제 열려있는 시간이 15초를 초과하기 전에 문닫힘 안전장치는 무효화되고, 감소된 동력 조건하에 닫히기 시작해야 한다.
자) 피난 층과 반대방향으로 운행 중인 피난용 엘리베이터는 가장 가까운 승강장에 정상적으로 정지되고 문은 열리지 않고 피난 층으로 복귀되어야 한다.
차) 피난 층으로 운행 중인 피난용 엘리베이터는 정지하지 않고 피난 층으로 운행되어야 한다. 피난용 엘리베이터가 중간의 다른 승강장으로 정지가 이미 시작되었다면 정상적으로 정지되고 문은 열리지 않고 피난 층까지 계속 이동한다.
카) 피난 층에 도착한 피난용 엘리베이터의 승강장문 및 카문은 열린 상태로 계속 유지되어야 한다.', 173057, 'true') ON CONFLICT (item_id) DO UPDATE SET text = EXCLUDED.text, section_title = EXCLUDED.section_title, updated_at = now();
INSERT INTO public.inspection_base_items (item_id, section_id, section_title, parent_section_id, text, sort_order, is_active) VALUES ('17.3.5.8', '17', '17.3.5.8 통제자의 피난용 엘리베이터 운전(피난운전)', '17.3.5', '17.3.5.8 통제자의 피난용 엘리베이터 운전(피난운전)
피난용 엘리베이터가 ''피난호출'' 조건하에 지정 피난 층에 정지하고 출입문이 열린 상태로 대기되면 카 내 조작반에서만 통제자에 의한 ''피난운전''이 시작되어야 하고, 다음 사항이 보장되어야 한다.
가) 카는 통제자가 제어할 수 있도록 카 내에서 ''피난운전''으로 전환되어야 하며, 이 전환은 7.9.3에 따른 비상잠금해제 삼각열쇠(피난운전 스위치)에 의해서 이루어져야 한다. 이 ''피난운전 스위치''는 ''해제'' 위치에서만 제거되어야 하며 7.9.3에서 규정된 비상잠금해제 삼각열쇠를 제외한 다른 유형의 키를 사용할 수 있다.
나) ''피난호출''이 17.3.5.7에 따른 외부 신호에 의해 시작된 경우, 피난용 엘리베이터는 피난 층에 위치한 ''피난호출 스위치'' 및 카 내의 ''피난운전 스위치''가 조작(전환)되기 전까지 운행되지 않아야 한다.
다) 카 내의 ''피난운전 스위치''가 통제자에 의해 "피난" 위치로 전환되었을 때, 키 스위치는 그 위치에 계속 유지되어야 하며, 해제는 오직 "해제" 위치에서만 가능해야 한다.
라) ''피난운전'' 중일 때 승강장 호출은 가능하지 않아야 하고 카 내 등록만 가능해야 한다.
마) 카 내에서 ''피난운전''으로 전환되면 카 내, 승강장 위치표시기 및 종합 방재실에는 "피난운전 중" 표시가 명확히 나타나야 한다.
바) 피난안전구역 또는 해당 층에 도착하면 피난용 엘리베이터 이용자(장애인, 노인 및 임산부 등을 포함)에게 적절한 탑승시간을 제공할 수 있도록 출입문이 개방되어 있어야 한다.
사) 문 열림 버튼 및 과부하감지장치는 작동이 가능한 상태이어야 한다. 다만, 문닫힘안전장치는 무효화되어야 한다.
아) 바)에 따른 탑승시간이 종료되면 카의 부하가 정격하중의 100 %에 이르지 않더라도 피난용 엘리베이터는 즉시 문을 닫고 피난 층으로 복귀되어야 한다. 이때 대피 신호를 받아 놓은 다른 층에 추가로 정지하는 것은 허용된다.
자) 카가 피난 층에 도착하면 출입문이 열리고 약 15초 이상 열려있어야 한다.
차) 카가 지정된 피난 층이 아닌 다른 층에 정지하고 있을 때 ''피난운전 스위치''가 "해제" 위치로 전환되면, 카는 즉시 문을 닫고 자동적으로 지정된 피난 층으로 복귀해야 한다.
카) 카가 지정된 피난 층에 접근이 불가능하거나 어떤 이유로 정지할 수 없을 경우 지정된 피난 층에서 가장 가까운 층 또는 미리 지정된 다른 층에 정상적으로 정지되어야 한다.
타) 주 전원 또는 보조 전원공급장치에 의해 초고층 건축물의 경우에는 2시간 이상, 준초고층 건축물의 경우에는 1시간 이상 ''피난운전'' 시킬 수 있어야 한다.', 173058, 'true') ON CONFLICT (item_id) DO UPDATE SET text = EXCLUDED.text, section_title = EXCLUDED.section_title, updated_at = now();
INSERT INTO public.inspection_base_items (item_id, section_id, section_title, parent_section_id, text, sort_order, is_active) VALUES ('17.3.5.9', '17', '17.3.5.9 피난 운행의 중지', '17.3.5', '17.3.5.9 피난 운행의 중지
피난용 엘리베이터가 어떤 이유로 운행이 중단되는 경우에는 승강장(피난안전구역)에서 대기하는 사람들에게 해당 상황을 알려주는 시각적 및 청각적 장치가 각 층 승강장에 제공되어야 한다.
청각적 장치는 음성신호장치이어야 하며, 소리는 35 dB(A)와 80 dB(A) 사이에서 조정이 가능해야 하고, 최초 설정은 75 dB(A)로 해야 한다.
이 장치의 접근 및 조정은 기술자 또는 인가된 관리자만 가능하도록 해야 한다.
비고: 피난용 엘리베이터의 운행이 중단된 경우에는 비상피난계단을 이용하도록 시각적 및 청각적으로 안내하는 것이 필요하다.
<2014년 7월 1일 이후 건축허가분부터 적용>', 173059, 'true') ON CONFLICT (item_id) DO UPDATE SET text = EXCLUDED.text, section_title = EXCLUDED.section_title, updated_at = now();
